#ifdef HOST_TESTING

            SetFunctionName("Vector3Plus(const fpu::Vector3PlusTemplate<FloatClassRHS> &_v)");
            ::rw::math::fpu::Vector4Template<double> doubleUnalignedVector;
            ::rw::math::fpu::Vector4Template<float> floatUnalignedVector;
            ::rw::math::fpu::Vector4Template<double> doubleAlignedVector;
            ::rw::math::fpu::Vector4Template<float> floatAlignedVector;

            doubleUnalignedVector.Set(
                0, 1, 2, 4
                );
            floatUnalignedVector.Set(
                0, 1, 2, 4
                );
            doubleAlignedVector.Set(
                0, 1, 2, 4
                );
            floatAlignedVector.Set(
                0, 1, 2, 4
                );

            Vector4 ref;
            ref.Set(
                0, 1, 2, 4
                );

            Vector4 test_doubleUnalignedVector(doubleUnalignedVector);
            Vector4 test_floatUnalignedVector(floatUnalignedVector);
            Vector4 test_doubleAlignedVector(doubleAlignedVector);
            Vector4 test_floatAlignedVector(floatAlignedVector);

            Validate(IsSimilar(test_doubleUnalignedVector, ref) &&
                IsSimilar(test_floatUnalignedVector, ref) &&
                IsSimilar(test_doubleAlignedVector, ref) &&
                IsSimilar(test_floatAlignedVector, ref));

#endif



