SetFunctionName("Mask4 CompLessThan(Vector4 a, Vector4 b)");
Vector4 va(1.0f, 1.0f, 2.0f, 2.0f );
Vector4 vb(1.0f, 2.0f, 1.0f, -1.0f );

Mask4 mask(CompLessThan(va, vb));
Validate(
    !mask.GetX().GetBool() &&
     mask.GetY().GetBool() &&
    !mask.GetZ().GetBool() &&
    !mask.GetW().GetBool()
);



