SetFunctionName("Vector4 Select(MaskScalar mask, Vector4 a, Vector4 b)");
Vector4 v1(1.0f, 2.0f, 3.0f, 4.0f);
Vector4 v2(10.0f, 20.0f, 30.0f, 40.0f);

Vector4 result1 = Select( MaskScalar(true), v1, v2 );
Vector4 result2 = Select( MaskScalar(false), v1, v2 );
Validate(
    result1 == v1 &&
    result2 == v2
);


