#endif



SetFunctionName("Vector4 Select(Mask4 mask, Vector4 a, Vector4 b)");
Vector4 v1(1.0f, 2.0f, 3.0f, 4.0f);
Vector4 v2(10.0f, 20.0f, 30.0f, 40.0f);
Vector4 ref1(1.0f, 2.0f, 30.0f, 40.0f);
Vector4 ref2(10.0f, 20.0f, 3.0f, 4.0f);
Mask4 mask1(true, true, false, false);
Mask4 mask2(false, false, true, true);

Vector4 result1 = Select( mask1, v1, v2 );
Vector4 result2 = Select( mask2, v1, v2 );
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector4 ClampToNegPosRange(value, range)");
Vector4 range(5.0f, 5.0f, 5.0f, 5.0f);
Vector4   v1( 7.0f,  3.0f, 0.0f, 0.0f);
Vector4   v2(-7.0f, -3.0f, 0.0f, 0.0f);
Vector4 ref1( 5.0f,  3.0f, 0.0f, 0.0f);
Vector4 ref2(-5.0f, -3.0f, 0.0f, 0.0f);
Vector4 result1 = ClampToNegPosRange( v1, range );
Vector4 result2 = ClampToNegPosRange( v2, range );
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector4 Permute<pattern>(value)");
Vector4 v(0.0f, 1.0f, 2.0f, 3.0f);
Vector4 ref1( 2.0f, 3.0f, 1.0f, 0.0f);
Vector4 ref2( 1.0f, 2.0f, 2.0f, 1.0f);
Vector4 result1 = Permute<0x2310>(v);
Vector4 result2 = Permute<0x1221>(v);
Validate(
    result1 == ref1 &&
    result2 == ref2
);



SetFunctionName("Vector4 unaligned load/store tests");
float buffer[8];

//Test every position with 16 byte alignment, then move 4 bytes forward each time
for (int i=0; i<8; i++)
  buffer[i] = static_cast<float>(i+1);

::rw::math::fpu::Vector4Template<float>* alignedVec = reinterpret_cast< ::rw::math::fpu::Vector4Template<float>*>(&buffer[0]);
Vector4 v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 1.0f && v.Y() == 2.0f && v.Z() == 3.0f  && v.W() == 4.0f);

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector4Template<float>*>(&buffer[1]);
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 2.0f && v.Y() == 3.0f && v.Z() == 4.0f  && v.W() == 5.0f);

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector4Template<float>*>(&buffer[2]);
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 3.0f && v.Y() == 4.0f && v.Z() == 5.0f  && v.W() == 6.0f);        

alignedVec = reinterpret_cast< ::rw::math::fpu::Vector4Template<float>*>(&buffer[3]); 
v = LoadUnAlignedPacked(*alignedVec);
Validate( v.X() == 4.0f && v.Y() == 5.0f && v.Z() == 6.0f  && v.W() == 7.0f);



SetFunctionName("Vector4 unaligned store tests");

float buffer[8];

//Test every position with 16 byte alignment, then move 4 bytes forward each time
for (int i=0; i<8; i++)
  buffer[i] = 0.0f;

Vector4 v2;

v2.Set(1.1f, 2.2f, 3.3f, 4.4f);
::rw::math::fpu::Vector4* unaligned = reinterpret_cast< ::rw::math::fpu::Vector4*>(&buffer[0]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[0] == 1.1f && buffer[1] == 2.2f && buffer[2] == 3.3f && buffer[3] == 4.4f);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector4*>(&buffer[1]);
StoreUnAlignedPacked( *unaligned, v2);
Validate( buffer[1] == 1.1f && buffer[2] == 2.2f && buffer[3] == 3.3f && buffer[4] == 4.4f);    

unaligned = reinterpret_cast< ::rw::math::fpu::Vector4*>(&buffer[2]);
StoreUnAlignedPacked( *unaligned, v2);
