Validate(IsEqualWithEpsilon(output.Y(), (float_test_type)0.17092f, (float_test_type)0.01f));
Validate(IsEqualWithEpsilon(output.Z(), (float_test_type)10.0f, (float_test_type)0.01f));
Validate(IsEqualWithEpsilon(output.W(), (float_test_type)1.0f, (float_test_type)0.01f));



